import java.util.Collections;
import org.junit.jupiter.api.Test;
import static java.util.Arrays.asList;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatExceptionOfType;

public class ChangeCalculatorEdgeTest {
    @Test public void zeroWithNoCoins() {
        assertThat(new ChangeCalculator(Collections.<Integer>emptyList()).computeMostEfficientChange(0)).isEmpty();
    }
    @Test public void positiveWithNoCoinsIsUnrepresentable() {
        assertThatExceptionOfType(IllegalArgumentException.class)
                .isThrownBy(() -> new ChangeCalculator(Collections.<Integer>emptyList()).computeMostEfficientChange(1))
                .withMessage("The total 1 cannot be represented in the given currency.");
    }
    @Test public void duplicatesAndInvalidDenominationsAreHandled() {
        assertThat(new ChangeCalculator(asList(0, -2, 3, 3, 5)).computeMostEfficientChange(9))
                .containsExactly(3, 3, 3);
    }
    @Test public void nonCanonicalSystemIsOptimal() {
        assertThat(new ChangeCalculator(asList(1, 3, 4)).computeMostEfficientChange(6))
                .containsExactly(3, 3);
    }
    @Test public void gcdUnreachableTotalIsRejected() {
        assertThatExceptionOfType(IllegalArgumentException.class)
                .isThrownBy(() -> new ChangeCalculator(asList(4, 6)).computeMostEfficientChange(11))
                .withMessage("The total 11 cannot be represented in the given currency.");
    }
    @Test public void representableTotalWithoutUnitCoin() {
        assertThat(new ChangeCalculator(asList(6, 9)).computeMostEfficientChange(15))
                .containsExactly(6, 9);
    }
}
